const GUIDE = (what) => ({ label: `ADAM System Check-Out and Trouble-Shooting Guide (Coleco, 1983), ${what}`, url: 'https://archive.org/download/ADAM_System_Check-Out_and_Trouble-Shooting_Guide_1983_Coleco/ADAM_System_Check-Out_and_Trouble-Shooting_Guide_1983_Coleco.pdf#page=4' });
const MC6801DB = (p, what) => ({ label: `Motorola MC6801/MC6803 data sheet (Single-Chip Microcomputer Data, 1984), ${what}`, url: `http://www.bitsavers.org/components/motorola/_dataBooks/1984_Motorola_Single-Chip_Microcomputer_Data.pdf#page=${p}` });
