const cartSummary = 'Thirty contacts, odd numbers on one row and even on the other (2 opposite 1). The cartridge sees D0-D7, A0-A14 and four 8 KB chip selects that the console decodes (U5 74LS138); there is no R/W line, so a cartridge is ROM only. Pin 30 gives +5 V, pin 29 logic ground and pin 13 the RF shield ground. Which row faces up in the slot is not stated in the sources: check pin 30 for +5 V before you trust the drawing\'s orientation. Dirty contacts here are the most common "dead game" fault.';

/* Controller DE-9: TRM 2.2.7 pin table and Fig. 2-5; redraw sheet 6 (J5, J6 DB9_Male); Deathskull as second source. */
const ctrlPins = [
  { n: 1, name: 'UP / KEY D0', type: 'io', desc: 'Joystick up while pin 8 is strobed; keypad code bit D0 while pin 5 is strobed. Read as data bit D0.', expect: 'Above 2.2 V idle; pulled to the strobe level when pressed' },
  { n: 2, name: 'DOWN / KEY D2', type: 'io', desc: 'Joystick down (pin 8 strobed) or keypad bit D2 (pin 5 strobed). Read as D2.', expect: 'Above 2.2 V idle' },
  { n: 3, name: 'LEFT / KEY D3', type: 'io', desc: 'Joystick left (pin 8 strobed) or keypad bit D3 (pin 5 strobed). Read as D3.', expect: 'Above 2.2 V idle' },
  { n: 4, name: 'RIGHT / KEY D1', type: 'io', desc: 'Joystick right (pin 8 strobed) or keypad bit D1 (pin 5 strobed). Read as D1.', expect: 'Above 2.2 V idle' },
  { n: 5, name: 'COMMON 1', type: 'ctrl', activeLow: true, desc: 'Keypad strobe from the console (U24 latch, set by an I/O write to $80). LOW selects the keypad and the right fire (arm) button.', expect: 'About -0.7 V low, +2.8 V high (TRM)' },
  { n: 6, name: 'FIRE', type: 'io', desc: 'Left fire while pin 8 is strobed; right fire (arm) while pin 5 is strobed. Read as D6.', expect: 'Above 2.2 V idle' },
  { n: 7, name: 'SPINNER B', type: 'io', desc: 'Spinner quadrature input B, read as D5 in either mode. Used by the driving module, Super Action and roller controllers. Not +5 V as on an Atari port.' },
  { n: 8, name: 'COMMON 0', type: 'ctrl', activeLow: true, desc: 'Joystick strobe from the console (U24 latch, set by an I/O write to $C0). LOW selects the joystick and the left fire button.', expect: 'About -0.7 V low, +2.8 V high (TRM)' },
  { n: 9, name: 'SPINNER A', type: 'io', desc: 'Spinner quadrature input A. Drives the Z80 maskable interrupt (INT) through the spinner circuit (U24, CR1/CR2), so a spinner edge interrupts the game.' },
];
const ctrlSummary = 'Two DE-9 ports, male on the console. There is no +5 V and no fixed ground pin: the console pulls pin 8 LOW to read the joystick and left fire, then pin 5 LOW to read the keypad and right fire, each through 120 Ω (R22/R23). Pins 1-4 and 6 come back through a 74LS541 buffer (U19 for port 1, U18 for port 2). An Atari joystick wired to pins 1-4, 6 and 8 works in joystick mode; the Atari +5 V on pin 7 lands on a spinner input. Idle inputs sit above 2.2 V; the Technical Manual says a buffer input below 2.2 V means a bad U18/U19.';

