/* The ADAM memory console's own port (P1): TRM 2.1.8 table, read from the module side. */
const adamExpPins = expBase.map(p => {
  const o = { ...p }; delete o.conflict;
  if (p.n === 35) return { n: 35, name: 'SND DISABLE', type: 'ctrl', desc: 'Sound chip 76489 disable (TRM: 0 V DC).' };
  if (p.n === 36) return { n: 36, name: 'NC', type: 'nc', desc: 'Not in use (TRM).' };
  if (p.n === 40) return { n: 40, name: '/BIORQ', type: 'ctrl', activeLow: true, desc: 'Buffered /IORQ (tristate output). The ColecoVision has a clock on this pin instead.' };
  if (p.n === 45) return { n: 45, name: '3.58 MHz', type: 'clock', desc: 'Buffered 3.58 MHz system clock.', expect: '3.58 MHz' };
  if (p.n === 56) return { n: 56, name: 'AUDIO', type: 'audio', desc: 'TRM prints "AUDIO 76489 RDY output". Treat as the sound chip line; probe before use.', verify: true };
  return o;
});

